import{_ as i,o as e,c as s,a3 as o}from"./chunks/framework.1Y430-yj.js";const u=JSON.parse('{"title":"Basic Factory Principles","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"基础基建原理","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8XrtahEh9tfuCux72hbfbI","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-8XrtahEh9tfuCux72hbfbI.md","filePath":"logistics/src/page-8XrtahEh9tfuCux72hbfbI.md","lastUpdated":null}'),n={name:"logistics/src/page-8XrtahEh9tfuCux72hbfbI.md"};function r(t,a,l,c,d,p){return e(),s("div",null,[...a[0]||(a[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="基础基建原理" aria-hidden="true"></span><h1 id="basic-factory-principles" tabindex="-1">Basic Factory Principles <a class="header-anchor" href="#basic-factory-principles" aria-label="Permalink to &quot;Basic Factory Principles&quot;">​</a></h1><blockquote><p>Source page ID: <code>8XrtahEh9tfuCux72hbfbI</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8XrtahEh9tfuCux72hbfbI" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>Severely unmaintained. Discuss whether this subpage&#39;s contents hierarchy is reasonable.</strong></span></p><p><span id="source-block-y7NDBIgu8isDQOXArHWW0Q"></span></p><span class="logistics-source-anchor" id="分流器和汇流器" aria-hidden="true"></span><h2 id="splitters-and-convergers" tabindex="-1">Splitters and Convergers <a class="header-anchor" href="#splitters-and-convergers" aria-label="Permalink to &quot;Splitters and Convergers&quot;">​</a></h2><p><span id="source-block-RPB2hRULTNApMTg45UlSNN"></span></p><span class="logistics-source-anchor" id="设备的相位、轮询、阻塞" aria-hidden="true"></span><h2 id="facility-phase-round-robin-servicing-and-blocking" tabindex="-1">Facility Phase, Round-Robin Servicing, and Blocking <a class="header-anchor" href="#facility-phase-round-robin-servicing-and-blocking" aria-label="Permalink to &quot;Facility Phase, Round-Robin Servicing, and Blocking&quot;">​</a></h2><p><span id="source-block-Oyx2mq8lNIlhIsxtNOwBM3"></span></p><span class="logistics-source-anchor" id="存取线和准入口" aria-hidden="true"></span><h2 id="depot-buses-and-control-ports" tabindex="-1">Depot Buses and Control Ports <a class="header-anchor" href="#depot-buses-and-control-ports" aria-label="Permalink to &quot;Depot Buses and Control Ports&quot;">​</a></h2><p><span id="source-block-NfGiRGZYbKjdrZcmwSyDsI"></span></p><span class="logistics-source-anchor" id="协议存储箱" aria-hidden="true"></span><h2 id="protocol-stash" tabindex="-1">Protocol Stash <a class="header-anchor" href="#protocol-stash" aria-label="Permalink to &quot;Protocol Stash&quot;">​</a></h2><p><span id="source-block-arv2ggXGKHsuEaiL0kZg6V"></span></p><span class="logistics-source-anchor" id="有理分流理论" aria-hidden="true"></span><h2 id="rational-splitting-theory" tabindex="-1">Rational Splitting Theory <a class="header-anchor" href="#rational-splitting-theory" aria-label="Permalink to &quot;Rational Splitting Theory&quot;">​</a></h2><p><span id="source-block-BMLkM2k9r6btZFG3eDCRf9"></span></p><span class="logistics-source-anchor" id="内部流通的有理分流器" aria-hidden="true"></span><h3 id="rational-splitters-with-internal-flow" tabindex="-1">Rational Splitters with Internal Flow <a class="header-anchor" href="#rational-splitters-with-internal-flow" aria-label="Permalink to &quot;Rational Splitters with Internal Flow&quot;">​</a></h3><p><span id="source-block-o4ulMUVo12T2A11pLRJzar"></span></p><span class="logistics-source-anchor" id="内部阻塞的有理分流器" aria-hidden="true"></span><h3 id="rational-splitters-with-internal-blocking" tabindex="-1">Rational Splitters with Internal Blocking <a class="header-anchor" href="#rational-splitters-with-internal-blocking" aria-label="Permalink to &quot;Rational Splitters with Internal Blocking&quot;">​</a></h3><p><span id="source-block-8AivCxQKTZlqERyOXW5EuV"></span></p><span class="logistics-source-anchor" id="pwm震荡热能池" aria-hidden="true"></span><h3 id="pwm-oscillating-thermal-banks" tabindex="-1">PWM Oscillating Thermal Banks <a class="header-anchor" href="#pwm-oscillating-thermal-banks" aria-label="Permalink to &quot;PWM Oscillating Thermal Banks&quot;">​</a></h3><p><span id="source-block-t9kjUHPVcj7vEOmLBvKnqD"></span></p><span class="logistics-source-anchor" id="优先级和溢流器" aria-hidden="true"></span><h2 id="priority-and-overflow-devices" tabindex="-1">Priority and Overflow Devices <a class="header-anchor" href="#priority-and-overflow-devices" aria-label="Permalink to &quot;Priority and Overflow Devices&quot;">​</a></h2><p><span id="source-block-EHhBNcPi9z2GuxnXC3X587"></span></p><span class="logistics-source-anchor" id="逻辑与、逻辑或、逻辑非" aria-hidden="true"></span><h3 id="logical-and-or-and-not" tabindex="-1">Logical AND, OR, and NOT <a class="header-anchor" href="#logical-and-or-and-not" aria-label="Permalink to &quot;Logical AND, OR, and NOT&quot;">​</a></h3><p><span id="source-block-U9hM3WXY5bA4qf5U4qE3am"></span></p><span class="logistics-source-anchor" id="阻尼理论与4n卡1现象" aria-hidden="true"></span><h3 id="damping-theory-and-the-4n-1-s-stall" tabindex="-1">Damping Theory and the 4n, 1 s Stall <a class="header-anchor" href="#damping-theory-and-the-4n-1-s-stall" aria-label="Permalink to &quot;Damping Theory and the 4n, 1 s Stall&quot;">​</a></h3><p><a href="./page-JN3ceSWPVQFlqvlfOsiR7k">Damping Theory, Revisions, and Extensions (Output Priority)</a></p><p><a href="./page-WJNJBOl9tQtVZ0GEuD8UaP">Damping Theory — Revised</a></p><p><span id="source-block-Us53G6Fq1qOnAB1JtpfakN"></span></p><span class="logistics-source-anchor" id="混带与混产" aria-hidden="true"></span><h2 id="mixed-belts-and-mixed-production" tabindex="-1">Mixed Belts and Mixed Production <a class="header-anchor" href="#mixed-belts-and-mixed-production" aria-label="Permalink to &quot;Mixed Belts and Mixed Production&quot;">​</a></h2><p><span id="source-block-a21wIHI7kMBJ062ZfbKwEi"></span></p><span class="logistics-source-anchor" id="环带时钟与沙漏时钟" aria-hidden="true"></span><h2 id="loop-belt-and-hourglass-clocks" tabindex="-1">Loop-Belt and Hourglass Clocks <a class="header-anchor" href="#loop-belt-and-hourglass-clocks" aria-label="Permalink to &quot;Loop-Belt and Hourglass Clocks&quot;">​</a></h2><p><span id="source-block-spGnfPdSVraF0np58q6Ptz"></span></p><span class="logistics-source-anchor" id="限流理论和长周期固体钟" aria-hidden="true"></span><h2 id="rate-limiting-theory-and-long-period-solid-clocks" tabindex="-1">Rate-Limiting Theory and Long-Period Solid Clocks <a class="header-anchor" href="#rate-limiting-theory-and-long-period-solid-clocks" aria-label="Permalink to &quot;Rate-Limiting Theory and Long-Period Solid Clocks&quot;">​</a></h2><p><span id="source-block-wWuTRL4v4083J95sW5rdD2"></span></p><span class="logistics-source-anchor" id="内部流通的有理限流器" aria-hidden="true"></span><h3 id="rational-flow-limiters-with-internal-flow" tabindex="-1">Rational Flow Limiters with Internal Flow <a class="header-anchor" href="#rational-flow-limiters-with-internal-flow" aria-label="Permalink to &quot;Rational Flow Limiters with Internal Flow&quot;">​</a></h3><p><span id="source-block-7R9931VccE38fQGWecdJ9R"></span></p><span class="logistics-source-anchor" id="内部阻塞的有理限流器" aria-hidden="true"></span><h3 id="rational-flow-limiters-with-internal-blocking" tabindex="-1">Rational Flow Limiters with Internal Blocking <a class="header-anchor" href="#rational-flow-limiters-with-internal-blocking" aria-label="Permalink to &quot;Rational Flow Limiters with Internal Blocking&quot;">​</a></h3><p><span id="source-block-63Gw6YCT379UUsIxenCJ8A"></span></p><span class="logistics-source-anchor" id="更复杂的物流体系" aria-hidden="true"></span><h3 id="more-complex-logistics-systems" tabindex="-1">More Complex Logistics Systems <a class="header-anchor" href="#more-complex-logistics-systems" aria-label="Permalink to &quot;More Complex Logistics Systems&quot;">​</a></h3><p><span id="source-block-2gXeYhYCoCuC01GqBfv0VH"></span></p><span class="logistics-source-anchor" id="蓝图的摆放顺序" aria-hidden="true"></span><h2 id="blueprint-placement-order" tabindex="-1">Blueprint Placement Order <a class="header-anchor" href="#blueprint-placement-order" aria-label="Permalink to &quot;Blueprint Placement Order&quot;">​</a></h2><p><span id="source-block-BHghb30fhpQwUubFd4QLFG"></span></p><span class="logistics-source-anchor" id="液气理论" aria-hidden="true"></span><h2 id="liquid-gas-theory" tabindex="-1">Liquid/Gas Theory <a class="header-anchor" href="#liquid-gas-theory" aria-label="Permalink to &quot;Liquid/Gas Theory&quot;">​</a></h2><p><span id="source-block-2B8Pu0ql6WXlq0qYbqukuu"></span></p><span class="logistics-source-anchor" id="液体钟" aria-hidden="true"></span><h3 id="liquid-clocks" tabindex="-1">Liquid Clocks <a class="header-anchor" href="#liquid-clocks" aria-label="Permalink to &quot;Liquid Clocks&quot;">​</a></h3><p><span id="source-block-7YPti9NugqqBqRBS2crZup"></span></p><span class="logistics-source-anchor" id="反应池与固液转换" aria-hidden="true"></span><h2 id="reactor-crucibles-and-solid-liquid-conversion" tabindex="-1">Reactor Crucibles and Solid/Liquid Conversion <a class="header-anchor" href="#reactor-crucibles-and-solid-liquid-conversion" aria-label="Permalink to &quot;Reactor Crucibles and Solid/Liquid Conversion&quot;">​</a></h2><p><span id="source-block-OhinWjoGtZso7YKb0WOuPR"></span></p><span class="logistics-source-anchor" id="多输入同时发生反应" aria-hidden="true"></span><h4 id="simultaneous-reactions-with-multiple-inputs" tabindex="-1">Simultaneous Reactions with Multiple Inputs <a class="header-anchor" href="#simultaneous-reactions-with-multiple-inputs" aria-label="Permalink to &quot;Simultaneous Reactions with Multiple Inputs&quot;">​</a></h4><p>Crucibles have virtual slots that can store items without physical slots. Filling an Expanded Crucible&#39;s extra slots with miscellaneous blocking items still does not make it behave like an ordinary crucible. Reactions that block an ordinary crucible do not block the expanded one; it may have more virtual slots.</p><p><span id="source-block-CdxP4h4o7oRy9BvXZllz0N"></span></p><span class="logistics-source-anchor" id="类溢流器作用" aria-hidden="true"></span><h4 id="overflow-like-behavior" tabindex="-1">Overflow-Like Behavior <a class="header-anchor" href="#overflow-like-behavior" aria-label="Permalink to &quot;Overflow-Like Behavior&quot;">​</a></h4><p>Materials inside the crucible prioritize output over reaction.</p><p><span id="source-block-50kXQ9bZCiVAPpHStZsrQx"></span></p><span class="logistics-source-anchor" id="输入输出特性" aria-hidden="true"></span><h4 id="input-output-behavior" tabindex="-1">Input/Output Behavior <a class="header-anchor" href="#input-output-behavior" aria-label="Permalink to &quot;Input/Output Behavior&quot;">​</a></h4><p>Item inputs and outputs always service ports round-robin, never changing into priority. If two liquid outputs carry the same liquid, they always service round-robin. Liquid inputs always use priority: earlier connections enter first. Everything except reaction-produced Liquid Xiranite prioritizes output.</p><p><span id="source-block-q7XChR42dU2AHd344rmzCq"></span></p><span class="logistics-source-anchor" id="物流桥代替" aria-hidden="true"></span><h4 id="replacing-a-belt-bridge" tabindex="-1">Replacing a Belt Bridge <a class="header-anchor" href="#replacing-a-belt-bridge" aria-label="Permalink to &quot;Replacing a Belt Bridge&quot;">​</a></h4><p>Usually called pass-through: the same item can enter and exit, somewhat like a belt running through the crucible.</p><p><span id="source-block-YUOFdiSzwhnfEAfYwn52LM"></span></p><span class="logistics-source-anchor" id="开关时的不同" aria-hidden="true"></span><h4 id="differences-when-switching-on-and-off" tabindex="-1">Differences When Switching On and Off <a class="header-anchor" href="#differences-when-switching-on-and-off" aria-label="Permalink to &quot;Differences When Switching On and Off&quot;">​</a></h4><p>Three crucible states:</p><p>Disabled (switched off): items enter but cannot leave; no reactions.</p><p>Standby (unpowered): items enter and leave freely; no reactions.</p><p>Operating (idle/producing): items enter and leave freely; reactions occur.</p><p>Unloaders similarly distinguish disabled from not disabled.</p><p><span id="source-block-9RG2JmGnEOHhTuIk2KhEKD"></span></p><span class="logistics-source-anchor" id="多口暗管" aria-hidden="true"></span><h2 id="conduit-manifolds" tabindex="-1">Conduit Manifolds <a class="header-anchor" href="#conduit-manifolds" aria-label="Permalink to &quot;Conduit Manifolds&quot;">​</a></h2><p><span id="source-block-JGymO4oX6mnI3uYZuKrZKx"></span></p><span class="logistics-source-anchor" id="固气转换、气液转换" aria-hidden="true"></span><h2 id="solid-gas-and-gas-liquid-conversion" tabindex="-1">Solid-Gas and Gas-Liquid Conversion <a class="header-anchor" href="#solid-gas-and-gas-liquid-conversion" aria-label="Permalink to &quot;Solid-Gas and Gas-Liquid Conversion&quot;">​</a></h2><p><span id="source-block-QD2hr2daemWzS8eUkzxFES"></span></p><span class="logistics-source-anchor" id="简易自适应" aria-hidden="true"></span><h3 id="simple-adaptive-operation" tabindex="-1">Simple Adaptive Operation <a class="header-anchor" href="#simple-adaptive-operation" aria-label="Permalink to &quot;Simple Adaptive Operation&quot;">​</a></h3></div>',1)])])}const b=i(n,[["render",r]]);export{u as __pageData,b as default};
